check($retention->run(1)===0 && is_file($target.'/'.$recoverFile) && !is_file($target.'/'.$recoverFile.'.o8-purge-'.$recoverDoc),'interrupted purge restores staged files when document still exists');
$manualSnapshot=$retention->manualInfo($u); $manualIds=array_column($manualSnapshot['items'],'id');
check($manualSnapshot['count']>=2 && in_array($unlimitedDoc,$manualIds,true) && in_array($recoverDoc,$manualIds,true) && !in_array($taggedTwo,$manualIds,true),'manual trash snapshot contains only the users own deleted documents');
check($retention->manualInfo($a)['count']>$manualSnapshot['count'] && $retention->manualInfo($b)['count']===0,'admin sees tenant trash while another tenant sees none');
$laterDoc=$docs->ingest($u,$tmp.'/sample.pdf','Trashed after confirmation.pdf'); $row=$docs->get($u,$laterDoc); $docs->status($u,$laterDoc,(int)$row['revision'],'trash');
check(!in_array($laterDoc,$manualIds,true),'documents trashed after confirmation are excluded from its snapshot');
