rejects(fn()=>$retention->manualPurge($u,$unlimitedDoc,(int)$docs->get($u,$unlimitedDoc)['revision']-1),'manual purge rejects stale document revision');
$manualRemoved=0; foreach ($manualSnapshot['items'] as $item) $manualRemoved+=(int)$retention->manualPurge($u,$item['id'],$item['revision']);
check($manualRemoved===$manualSnapshot['count'] && $docs->trashCount($u)===1 && !is_file($target.'/'.$recoverFile),'manual purge permanently deletes snapshot files even when retention is unlimited');
$adminSnapshot=$retention->manualInfo($a); foreach ($adminSnapshot['items'] as $item) $retention->manualPurge($a,$item['id'],$item['revision']);
check($docs->trashCount($a)===0 && $docs->trashCount($u)===0,'admin can empty all remaining tenant trash');
$admin->updateUser($a,$u->id(),(int)$u->row['auth_version'],'Blocked','user',false);
rejects(fn()=>$docs->get($u,$own),'revoked actor cannot read');
rejects(fn()=>$docs->ingest($u,$tmp.'/sample.pdf','stale.pdf'),'revoked actor cannot ingest');
$txtId=$docs->ingest($a,$tmp.'/note.txt','note.txt'); $txtFile=sql("SELECT relative_path,mime_type FROM document_files WHERE document_id=? AND role='original'",[$txtId])->fetch();
$odtId=$docs->ingest($a,$tmp.'/note.odt','note.odt'); $odtFile=sql("SELECT relative_path,mime_type FROM document_files WHERE document_id=? AND role='original'",[$odtId])->fetch();
check($txtFile['mime_type']==='text/plain' && str_ends_with((string)$txtFile['relative_path'],'.txt') && $odtFile['mime_type']==='application/vnd.oasis.opendocument.text' && str_ends_with((string)$odtFile['relative_path'],'.odt'),'TXT and ODT originals use regular safe ingestion');
$deletion=new TenantDeletion($db,$root);
sql('INSERT INTO platform_settings (setting_key,value_json) VALUES (?,?)',['trash.retention.pending',json_encode(['tenant'=>$a->tenantId(),'document'=>$recoverDoc,'files'=>[]])]);
rejects(fn()=>$deletion->start($op,$a->tenantId(),$uuid,'Alpha'),'tenant deletion waits for pending trash purge recovery');
$retention->run(1);
$job=$deletion->start($op,$a->tenantId(),$uuid,'Alpha');
rejects(fn()=>$docs->open($a,$id),'deleting tenant cannot stream');
$steps=0; while ($job['phase']!=='done' && ++$steps<100) $job=$deletion->step($op,$a->tenantId());
check($job['phase']==='done' && !is_dir($target),'tenant deletion handles real originals and storage marker');
check(is_dir($base.'/'.$second),'other tenant storage preserved');
